export const weapons=['맨손','검','도','창','활','지팡이'];
export const elements=['물','불','흙','바람','나무','쇠','번개'];
export function initial(name){return {version:1,name,scene:'arrival',path:null,trial:null,element:null,weapon:null,hp:10,energy:6,control:0,insight:0,skill:0,trust:0,training:0,flags:[],journal:[],last:'',ending:null};}
const option=(id,title,hint='')=>({id,title,hint});
const pathName=s=>s.path==='inner'?'쌓는 길':s.path==='outer'?'끌어 쓰는 길':'아직 열지 않은 길';
export {pathName};
export function scene(s){
 const inner=s.path==='inner';
 switch(s.scene){
 case 'arrival':return {chapter:1,title:'아직 쓰이지 않은 이름',text:[`운양의 산길 끝, 오래된 돌문에 「모든 길은 첫 숨에서 시작된다」는 문장이 새겨져 있었다. 당신은 여행 보따리를 고쳐 메고 그 아래를 지났다.`,`이곳은 여러 문파와 학파가 초심자를 가르치는 공동 수련처, 여울원. 검을 찬 제자 옆에서 누군가는 아무 무기도 없이 허공의 물방울을 움직였다.`,`접수대의 노인이 빈 명부 위에 당신의 이름, ‘${s.name}’을 적었다.`],quote:'“어디서 왔느냐보다, 여기서 무엇을 하느냐가 중요하지.”',choices:[option('observe','마당의 수련을 유심히 살핀다','관찰로 시작한다 · 통찰 +1'),option('help','무거운 짐을 든 제자를 돕는다','사람에게 다가간다 · 동료 신뢰 +1')]};
 case 'spring':return {chapter:1,title:'샘이 가르치는 것',text:['새벽, 안내역인 제자 이솔이 당신을 샘가로 데려갔다. 물 위에 떨어진 잎이 흐름을 거슬러 천천히 돌았다.','“숨이야. 물에도, 돌에도, 네 안에도 있어.” 이솔은 한 손을 배에, 다른 손을 샘 위에 뻗었다.','스승은 아직 길이 열리지 않은 지금만 두 방식을 가볍게 느껴 볼 수 있다고 했다. 어느 하나를 몸에 새기는 것은 그다음이다.'],choices:[option('try-inner','호흡을 따라 숨을 몸 안에 머무르게 한다','쌓는 길을 체험한다 · 아직 확정되지 않음'),option('try-outer','샘 주위의 숨을 손끝으로 이끌어 본다','끌어 쓰는 길을 체험한다 · 아직 확정되지 않음')]};
 case 'commit':return {chapter:1,title:s.trial==='inner'?'안으로 고이는 물결':'손끝을 지나는 흐름',text:s.trial==='inner'?['들이마신 숨이 아랫배에 작고 따뜻한 무게를 남겼다. 숨을 내쉬어도, 그 온기는 사라지지 않았다.','스승이 고개를 끄덕였다. “그것을 쌓아 네 힘으로 만드는 것이 무인의 길이다. 바깥의 숨이 드문 땅에서도, 네 안에 남은 힘을 쓸 수 있지.”']:['샘물 위의 작은 잎이 손끝을 따라 움직였다. 몸에 힘을 담지 않았는데도, 당신을 지나간 흐름이 세상을 건드렸다.','스승이 고개를 끄덕였다. “쌓지 않고 그 자리에서 끌어 쓰는 마법사의 길이다. 주위의 흐름을 읽고, 그것을 네 뜻에 맞게 이끄는 것이지.”'],quote:'“한 길을 열면 몸이 그 길에 맞춰진다. 인간은 두 길을 함께 갈 수 없다. 충분히 느껴 보고 정하거라.”',choices:[option('commit',s.trial==='inner'?'내 안에 숨을 쌓는 길을 연다':'바깥의 숨을 끌어 쓰는 길을 연다','이 선택으로 길이 확정됩니다 · 이후 변경 불가'),option('switch','다른 방식도 느껴 본다','확정 전에 다른 길을 체험한다')]};
 case 'element':return {chapter:1,title:'당신의 숨이 띠는 결',text:['길을 열자 전에는 구별할 수 없던 감각이 선명해졌다. 스승이 일곱 개의 작은 돌을 앞에 내려놓았다.','“결은 새로 고르는 옷이 아니다. 네가 타고난 숨의 모양이지. 무엇이 네 안에서 응답하느냐?”','눈을 감고, 가장 또렷하게 다가오는 감각에 귀를 기울였다.'],choices:elements.map((x,i)=>option('element-'+i,['차갑고 유연하게 스며드는 물','어둠 속에서도 번져 가는 불','깊고 단단하게 받치는 흙','어디에도 머물지 않는 바람','천천히 뻗어나가 이어지는 나무','한 점으로 곧게 벼려지는 쇠','찰나에 빛나고 사라지는 번개'][i],`타고난 결 설정 · ${x}`))};
 case 'weapon':return {chapter:2,title:'손에 남는 감각',text:[`무기고의 문이 열렸다. 낡은 수련 도구들이 가지런히 걸려 있었다.`,`“${inner?'쌓은 숨을 어떻게 펼칠지는':'외부의 숨을 무엇으로 이끌지는'} 네가 정해라. 검을 쥐었다고 모두 무인인 것은 아니고, 맨손이라고 마법을 못 쓰는 것도 아니니.”`,`한 가지를 골라 첫 수련을 시작하자. 길과 달리, 도구는 나중에 다른 것을 배울 수 있다.`],choices:weapons.map((x,i)=>option('weapon-'+i,x,['몸 자체를 무기이자 매개로 · 밀착과 타격','정확한 궤적과 균형 · 흘리기와 찌르기','무게를 실은 한 번의 궤적 · 강한 돌파','긴 거리와 곧은 힘 · 접근 제어','거리와 호흡의 타이밍 · 원거리 견제','흐름을 짚는 긴 매개 · 제어와 방어'][i]))};
 case 'practice':return {chapter:2,title:'작은 반복이 길이 된다',text:[`당신은 ${s.weapon==='맨손'?'빈손으로 자세를 잡았다':s.weapon+'을 고쳐 쥐었다'}. ${s.element}의 숨은 아직 서툴게 흔들렸다.`,inner?'몸 안에 쌓인 힘을 끝까지 유지하는 일과 정확한 순간에 꺼내는 일은 달랐다.':'흐름을 느끼는 것과 그 흐름을 원하는 모양으로 유지하는 것은 달랐다.',`해가 기울기까지 ${3-s.training}번 더 수련할 시간이 있다. 마당 한쪽에서는 이솔도 땀을 닦으며 당신을 기다렸다.`],choices:[option('control',inner?'호흡을 고르게 하며 숨을 다스린다':'작은 흐름을 오래 유지한다','제어 +1 · 숨 회복 1'),option('skill',`${s.weapon==='맨손'?'발디딤과 타격':s.weapon+'의 기본 동작'}을 반복한다`,'숙련 +1 · 체력 소모 1'),option('insight','주변의 숨이 달라지는 곳을 찾는다','통찰 +1'),option('trust','이솔과 서로의 빈틈을 짚어 준다','신뢰 +1 · 체력 회복 1')]};
 case 'mission':return {chapter:3,title:'산 아래로 가는 두 사람',text:['첫 심부름은 단순했다. 산 아래 마을에 약초 꾸러미를 전하고, 해가 지기 전에 돌아올 것. 이솔이 당신과 함께 나섰다.','갈림길에 닿자 오래된 수로 아래에서 돌이 부딪치는 소리가 났다. 마을로 가는 다리의 밧줄 하나가 끊어져 있었다.','다리 건너에는 약초를 기다리는 마을 사람과 겁에 질린 아이가 있었다. 수풀에서는 얼굴을 가린 자가 걸어 나왔다.'],quote:'“꾸러미를 두고 가. 그러면 다리는 건너지 않아도 돼.”',choices:[option('read','상대보다 먼저 주변의 흐름을 읽는다','통찰이 높으면 매복을 발견 · 숨 소모 1'),option('guard','이솔과 아이를 등 뒤에 두고 맞선다','신뢰가 높으면 이솔이 후방을 맡음'),option('rush','상대가 자리를 잡기 전에 거리를 좁힌다','숙련이 높으면 선수를 잡음 · 체력 소모 1')]};
 case 'combat':{const descriptions={맨손:inner?'상대의 팔 안쪽으로 파고들어 장타를 넣는다':'손바닥 앞에 숨을 모아 가까운 거리에서 터뜨린다',검:inner?'공격을 흘리고 빈틈에 검끝을 뻗는다':'검끝으로 결의 궤적을 그려 흐름을 쏘아 보낸다',도:inner?'발을 딛고 도에 실은 숨을 한 번에 내리긋는다':'도의 넓은 궤적을 따라 숨의 파동을 보낸다',창:inner?'창끝에 숨을 실어 상대의 접근을 끊는다':'창끝을 기준으로 숨의 경계를 세운다',활:inner?'한 호흡을 화살에 실어 정확히 놓는다':'시위의 떨림으로 바깥의 숨을 화살에 잇는다',지팡이:inner?'지팡이를 짚고 회전해 상대의 중심을 친다':'지팡이 끝에서 주위의 숨을 한 점으로 모은다'};return {chapter:3,title:'처음으로 겨누는 힘',text:[s.flags.includes('advantage')?'당신은 상대의 움직임을 한발 앞서 읽었다. 먼저 잡은 기회를 놓치지 말아야 한다.':'상대의 짧은 칼이 빛났다. 수련장에서 배운 동작이 갑자기 멀게 느껴졌다.',`손끝에 ${s.element}의 숨이 일었다. ${inner?'단전에 모아 둔 힘이 호흡을 따라 움직였다.':'주변에 흐르던 힘이 당신이 만든 길로 모여들었다.'}`,'이솔은 끊어진 밧줄을 붙들었다. 오래 버틸 수는 없을 것이다.'],choices:[option('technique',descriptions[s.weapon],`숙련 2 이상이면 확실한 제압 · 숨 소모 2${s.flags.includes('advantage')?' · 선점으로 숙련 조건 1 감소':''}`),option('flow',`${s.element}의 숨으로 적의 발밑을 흐트러뜨린다`,`제어 2 또는 통찰 2 이상이면 성공 · 숨 소모 2`),{...option('cooperate','이솔과 신호를 맞춰 양쪽에서 압박한다',s.trust>=2?'신뢰 2 이상 · 협력으로 제압 · 숨 소모 1':'신뢰 2 필요 · 함께 수련하거나 후방을 맡겨야 함'),disabled:s.trust<2}]};}
 case 'bridge':return {chapter:3,title:'끊어지기 직전의 것',text:[s.flags.includes('won')?'얼굴을 가린 자는 무기를 놓고 숲으로 달아났다. 첫 실전은 끝났지만, 밧줄이 찢어지는 소리가 뒤따랐다.':'힘이 흐트러진 순간, 칼끝이 어깨를 스쳤다. 이솔이 돌을 던져 상대를 물러나게 했다. 이제 다리가 무너지기 전에 움직여야 한다.','약초 꾸러미가 다리 난간에 걸려 있었다. 그 아래, 아이가 매달린 나무판이 점점 기울었다.','모든 것을 붙들려면 흐름을 정확히 읽거나, 이솔과 힘을 나눠야 한다.'],choices:[option('child','아이부터 안전한 곳으로 끌어 올린다','사람을 우선한다 · 약초 일부를 잃는다'),{...option('both',inner?'숨을 다리에 싣고 이솔과 밧줄을 당긴다':'다리 아래의 숨을 이끌어 이솔을 돕는다',s.trust>=2?'신뢰로 역할을 나눈다 · 숨 소모 2':'제어 + 통찰 3 이상 필요 · 숨 소모 2'),disabled:s.energy<2||(s.trust<2&&s.control+s.insight<3)},option('herbs','꾸러미를 건네고 이솔에게 아이를 맡긴다','마을의 약을 지킨다 · 이솔의 부담과 부상')]};
 case 'night':return {chapter:4,title:'돌아오는 길의 침묵',text:[s.ending==='together'?'마을에 아이와 약초가 함께 도착했다. 이솔은 힘이 풀린 손으로 물그릇을 쥐고 웃었다.':s.ending==='child'?'아이는 무사히 가족에게 돌아갔다. 약초는 절반밖에 남지 않았지만, 마을 사람들은 당신에게 따뜻한 밥을 내주었다.':'약초 꾸러미는 무사했다. 아이도 살아 돌아왔지만, 이솔은 다친 팔을 감춘 채 말이 없었다.','수련처로 돌아오는 길, 낮에 쓴 힘의 감각이 되살아났다. 잘한 일과 놓친 일이 함께 떠올랐다.','스승은 결과를 듣고도 바로 평가하지 않았다. 대신 질문 하나를 건넸다.'],quote:'“오늘의 너에게, 내일의 너는 무엇을 더해 주고 싶으냐?”',choices:[option('resolve-control','위태로운 순간에도 흔들리지 않는 호흡','제어 +1 · 제어를 바탕으로 첫 기술 완성'),option('resolve-skill','망설임을 끝낼 수 있는 한 번의 동작','숙련 +1 · 무기를 바탕으로 첫 기술 완성'),option('resolve-trust','누군가와 함께 짊어지는 법','신뢰 +1 · 동료와 호흡을 맞추는 첫 기술 완성')]};
 case 'ending':return {chapter:4,title:'이제, 당신의 길이 시작된다',text:[`명부에 이름을 적던 날, 당신은 길이 없는 제자였다. 이제 ${s.name}에게는 ${pathName(s)}과 ${s.element}의 결, 그리고 스스로 얻은 첫 기술이 있다.`,s.ending==='together'?'힘을 나누는 선택이 두 가지를 함께 지켰다. 이솔은 다음 심부름도 당신과 가겠다고 했다.':s.ending==='child'?'당신은 손에 쥔 물건보다 사람을 먼저 붙들었다. 마을의 아이는 당신의 이름을 오래 기억할 것이다.':'당신은 많은 이에게 필요한 약을 지켰다. 다친 이솔과 나눠야 할 이야기는 아직 남아 있다.','산 너머 청운문에서 낯선 자들이 승천지를 묻고 다닌다는 소문이 들려왔다. 여울원에서의 작은 시작은, 곧 한뉘의 더 큰 흐름과 만날 것이다.'],choices:[]};
 default:throw new Error('알 수 없는 장면');
 }
}
export function choose(state,id){
 const s=structuredClone(state);const current=scene(s);const c=current.choices.find(x=>x.id===id);if(!c||c.disabled)throw new Error('선택할 수 없습니다.');
 s.journal.push({scene:current.title,choice:c.title});s.last='';
 switch(s.scene){
 case 'arrival':if(id==='observe'){s.insight++;s.last='수련자마다 숨의 흐름이 다르다는 것을 알아차렸다. · 통찰 +1';}else{s.trust++;s.last='이솔이 당신의 이름을 기억했다. · 신뢰 +1';}s.scene='spring';break;
 case 'spring':s.trial=id==='try-inner'?'inner':'outer';s.scene='commit';break;
 case 'commit':if(id==='switch'){s.trial=s.trial==='inner'?'outer':'inner';}else{s.path=s.trial;s.control++;s.scene='element';s.last=`${pathName(s)}이 열렸다. · 제어 +1`;}break;
 case 'element':s.element=elements[Number(id.split('-')[1])];s.scene='weapon';s.last=`타고난 ${s.element}의 결이 응답했다.`;break;
 case 'weapon':s.weapon=weapons[Number(id.split('-')[1])];s.skill++;s.scene='practice';s.last=`${s.weapon}의 첫 감각을 익혔다. · 숙련 +1`;break;
 case 'practice':s[id]++;s.training++;if(id==='control')s.energy=Math.min(6,s.energy+1);if(id==='skill')s.hp--;if(id==='trust')s.hp=Math.min(10,s.hp+1);s.last={control:'작은 흐름이 안정되었다. · 제어 +1',skill:'반복한 동작이 몸에 남았다. · 숙련 +1, 체력 -1',insight:'그늘 아래와 샘가의 숨은 달랐다. · 통찰 +1',trust:'이솔과 서로의 약점을 알게 되었다. · 신뢰 +1, 체력 +1'}[id];if(s.training===3)s.scene='mission';break;
 case 'mission':{let advantage=false;if(id==='read'){s.energy--;advantage=s.insight>=2;s.last=advantage?'수풀에 숨은 두 번째 그림자를 먼저 발견했다. · 선점 획득':'낯선 흐름을 살피는 동안 상대가 다가왔다. · 숨 -1';}if(id==='guard'){s.trust++;advantage=s.trust>=2;s.last='이솔이 당신의 뒤를 맡았다. · 신뢰 +1'+(advantage?' · 선점 획득':'');}if(id==='rush'){s.hp--;advantage=s.skill>=2;s.last=advantage?'익힌 발디딤으로 먼저 유리한 자리를 잡았다. · 체력 -1, 선점 획득':'거리를 좁혔지만 상대도 칼을 뽑았다. · 체력 -1';}if(advantage)s.flags.push('advantage');s.scene='combat';break;}
 case 'combat':{const cost=id==='cooperate'?1:2;const ok=s.energy>=cost&&(id==='cooperate'?s.trust>=2:id==='technique'?s.skill>=(s.flags.includes('advantage')?1:2):s.control>=2||s.insight>=2);s.energy=Math.max(0,s.energy-cost);if(ok){s.flags.push('won');s.last='익혀 둔 힘이 위기에서 응답했다. · 적 제압, 숨 -'+cost;}else{s.hp=Math.max(1,s.hp-3);s.last='힘이 흔들려 어깨를 다쳤다. 이솔이 퇴로를 열었다. · 체력 -3, 숨 -'+cost;}s.scene='bridge';break;}
 case 'bridge':if(id==='both'){s.energy-=2;s.ending='together';s.trust++;s.last='둘이 함께 아이와 약초를 지켰다. · 숨 -2, 신뢰 +1';}else if(id==='child'){s.ending='child';s.trust++;s.last='아이를 구했다. 약초 일부가 계곡으로 떨어졌다. · 신뢰 +1';}else{s.ending='herbs';s.trust=Math.max(0,s.trust-1);s.flags.push('isol-injured');s.last='약초와 아이는 무사했지만, 이솔이 팔을 다쳤다. · 신뢰 -1';}s.scene='night';break;
 case 'night':{const stat=id.replace('resolve-','');s[stat]++;s.flags.push('art-'+stat);s.scene='ending';s.last='첫 깨달음을 얻었다. · '+{control:'제어',skill:'숙련',trust:'신뢰'}[stat]+' +1';break;}
 }
 return s;
}
export function art(s){const mode=s.flags.find(x=>x.startsWith('art-'))?.slice(4);return mode==='control'?`${s.element}결 · 고른 숨`:mode==='trust'?`${s.element}결 · 잇는 호흡`:`${s.element}결 · ${s.weapon==='맨손'?'첫 장타':s.weapon+'의 첫 궤적'}`;}
